def dur(n):
    with wave.open(f"{d}/wav/{n}.wav") as w: return w.getnframes()/w.getframerate()
cards = ""
for k, title, items in G:
    cards += f'<section><h2><span class="tag">{k}</span>{title}</h2><div class="grid">'
    for n, t, desc, tech in items:
        loop = " loop" if "loop" in n else ""
        cards += f'<article><h3>{t}</h3><p class="file">{n}.wav · {dur(n):.1f} c · 44.1 кГц стерео</p><audio controls preload="none"{loop} src="wav/{n}.wav"></audio><p>{desc}</p><p class="tech"><b>Техника:</b> {html.escape(tech)}</p></article>'
    cards += "</div></section>"
